import { EPUBCHECK_VERSION } from "epubcheck-standalone";

export const HELP_OUTPUT = `EPUBCheck v${EPUBCHECK_VERSION}\n\nWhen running this tool, the first argument should be the name (with the path)\nof the file to check.\n\nTo specify a validation profile (to run checks against a specific EPUB 3 profile\nor extension specification), use the -profile option:\n\nValidation profiles supported:\n--profile default        = the default validation profile\n--profile dict           = validates against the EPUB Dictionaries and Glossaries specification\n--profile edupub         = validates against the EDUPUB Profile\n--profile idx            = validates against the EPUB Indexes specification\n--profile preview        = validates against the EPUB Previews specification\n\nIf checking a non-epub file, the epub version of the file must\nbe specified using -v and the type of the file using -mode.\nThe default version is: 3.0.\n\nModes and versions supported:\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo  -v 3.0        = for Media Overlays validation\n--mode exp               = for expanded EPUB archives\n\nThis tool also accepts the following options:\n--save                   = saves the epub created from the expanded epub\n--out <file>             = output an assessment XML document file (use - to output to console)\n--xmp <file>             = output an assessment XMP document file (use - to output to console)\n--json <file>            = output an assessment JSON document file (use - to output to console)\n-m <file>                = same as --mode\n-p <profile>             = same as --profile\n-o <file>                = same as --out\n-x <file>                = same as --xmp\n-j <file>                = same as --json\n--maxOfEachMessage NUM   = limit the number of messages reported for each message-ID-and-text combination to NUM.\n                           This option only applies when producing a report in one of the JSON or XML formats.\n                           By default, if this option is not set, the report will only include a maximum of 25\n                           messages for each message-ID-and-text combination.\n                           The keyword 'unlimited' or a negative value can be used to unset the limit and include\n                           all the messages to the report.\n\n--failonwarnings         = By default, the tool returns a 1 if errors are found in the file or 0 if no errors\n                           are found.  Using --failonwarnings will cause the process to exit with a status of\n                           1 if either warnings or errors are present and 0 only when there are no errors or warnings.\n-q, --quiet              = no message on console, except errors, only in the output\n-f, --fatal              = include only fatal errors in the output\n-e, --error              = include only error and fatal severity messages in ouput\n-w, --warn               = include fatal, error, and warn severity messages in output\n-u, --usage              = include ePub feature usage information in output\n                           (default is OFF); if enabled, usage information will\n                           always be included in the output file\n--locale <locale>        = output localized messages according to the provided IETF BCP 47 language tag string.\n\n-l, --listChecks [<file>]       = list message ids and severity levels to the custom message file named <file>\n                                  or the console\n-c, --customMessages [<file>]   = override message severity levels as defined in the custom message file named <file>\n\n--version                = displays the EPUBCheck version\n\n-h, -? or --help         = displays this help message\n\n`;

export const HELP_OUTPUT_BY_LOCALE: Record<string, string> = {
  "da": `EPUBCheck v${EPUBCHECK_VERSION}\n\nDet første parameter, der skal sendes til dette værktøj, skal være filstien til den fil,\ndu vil kontrollere.\n\nFor at angive en valideringsprofil (og kontrollere op imod en bestemt EPUB 3 profil\neller udvidet specifikation), skal du anvende en -profil-indstilling:\n\nValideringsprofiler som understøttes:\n--profile default        = standardvalideringsprofilen\n--profile dict           = valideret op imod "EPUB Dictionaries and Glossaries"-specifikationen\n--profile edupub         = valideret op imod "EDUPUB Profile"\n--profile idx            = valideret op imod "EPUB Indexes"-specifikationen\n--profile preview        = valideret op imod "EPUB Previews"-specifikationen\n\nHvis der kontrolleres en fil, som ikke er en zippet EPUB, skal EPUB versionsnummeret, som der skal kontrolleres imod, angives med parameteret -v, samt Typen af ​​filen med parameteret --mode\nStandardversion til validering er: 3.0.\n\nModus og versioner som understøttes:\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo  -v 3.0        = til Media Overlays version 3.0\n--mode exp               = til udpakkede EPUB-arkiver\n\nEPUBCheck accepterer disse ekstra muligheder:\n--save                   = genererer en EPUB ud fra den udpakkede mappe\n--out <file>             = gemmer resultatet af validering i XML-format (brug - for at skrive til konsol)\n--xmp <file>             = gemmer resultatet af valideringen i XMP-format (brug - for at skrive til konsol)\n--json <file>            = gemmer resultatet af validering i JSON-format (brug - for at skrive til konsol)\n-m                       = synonym for --mode\n-p <profile>             = synonym for --profile\n-o <file>                = synonym for --out\n-x <file>                = synonym for --xmp\n-j <file>                = synonym for --json\n--failonwarnings         = som standard afsluttes EPUBCheck med ExitCode 1 hvis der blev fundet fejl i filen, og med ExitCode 0 hvis der ikke blev fundet fejl.\n                           Ved brug af --failonwarnings vil EPUBCheck blive klar til afslutning\n                           med ExitCode 1 når der er advarsler, og ExitCode 0 ved ingen fejl eller mangler.\n-q, --quiet              = kun fejl udsendes på konsollen\n-f, --fatal              = brug kun fatale fejl\n-e, --error              = vis kun fatale fejl og fejl\n-w, --warn               = fatale fejl, fejl og advarsler\n-u, --usage              = output information om brug af specifikke EPUB-funktioner \n                           (deaktiveret som standard); hvis aktiveret, er informationen\n                           altid inkluderet i outputfilen\n--locale <locale>        = information af resultaterne i det givne sprog, hvis en oversættelse er tilgængelig (i henhold til IETF BCP 47-standarden).\n\n-l, --listChecks [<file>]       = output af alle meddelelses-id"<file>er og fejlniveauer i en brugerdefineret fil<file>\n                                  eller på konsollen\n-c, --customMessages [<file>]   = overstyrer fejlniveauet for EPUBCheck som angivet i den brugerdefinerede fil <file>\n\n--version                = viser EPUBCheck versionsnummer\n\n-h, -? eller --help      = viser denne hjælp\n\n`,
  "de": `EPUBCheck v${EPUBCHECK_VERSION}\n\nDer erste Parameter der an dieses Tool übergeben werden sollte,\nsollte der Dateipfad der zu prüfenden Datei sein.\n\nUm ein Validierungsprofil anzugeben, verwende den Parameter --profile\nValidierungsprofile können verwendet werden, um gegen ein spezielles EPUB 3-Profil\noder eine erweiterte Spezifikation zu validieren.\n\nUnterstützte Validierungsprofile:\n--profile default       = Das Standard-Validierungsprofil\n--profile dict          = Validiert gegen die "EPUB Dictionaries and Glossaries"-Spezifikation\n--profile edupub        = Validiert gegen das "EDUPUB"-Profil\n--profile idx           = Validiert gegen die "EPUB Indexes"-Spezifikation\n--profile preview       = Validiert gegen die "EPUB Previews"-Spezifikation\n\nWenn eine Datei geprüft wird die kein gezipptes EPUB ist,\ndann muss die EPUB-Versionsnummer gegen die geprüft werden soll\nmit dem Parameter -v angegeben werden, sowie der Typ der Datei\nmit dem Parameter --mode\nDie Standard-Version zur Validierung ist 3.0\n\nUnterstützte Werte für die Parameter --mode und -v:\n--mode opf -v 2.0       = Für OPF-Dateien der Version 2.0\n--mode opf -v 3.0       = Für OPF-Dateien der Version 3.0\n--mode xhtml -v 2.0     = Für XHTML-Dateien der Version 2.0\n--mode xhtml -v 3.0     = Für XHTML-Dateien der Version 3.0\n--mode svg -v 2.0       = Für SVG-Dateien der Version 2.0\n--mode svg -v 3.0       = Für SVG-Dateien der Version 3.0\n--mode nav -v 3.0       = Für EPUB-Navigationsdokumente der Version 3.0\n--mode mo  -v 3.0       = Für EPUB-MediaOverlays der Version 3.0\n--mode exp              = Für entpackte EPUB-Archive\n\nEPUBCheck akzeptiert diese weiteren Optionen:\n--save                  = generiert ein EPUB aus dem entpackten Ordner\n--out <datei>           = speichert das Ergebnis der Validierung im XML-Format\n--xmp <datei>           = speichert das Ergebnis der Validierung im XMP-Format\n--json <datei>          = speichert das Ergebnis der Validierung im JSON-Format\n-m <datei>              = Synonym zu --mode\n-p <profile>            = Synonym zu --profile\n-o <datei>              = Synonym zu --out\n-x <datei>              = Synonym zu --xmp\n-j <datei>              = Synonym zu --json\n--failonwarnings        = Standardmäßig wird EPUBCheck mit ExitCode 1 beendet falls Fehler im EPUB gefunden wurden\n                          und mit ExitCode 0, falls keine Fehler gefunden wurden. Bei Nutzung von --failonwarnings\n                          wird EPUBCheck auch bereits bei Auftreten von Warnungen mit ExitCode 1 beendet.\n-q, --quiet             = Nur Fehler werden auf der Konsole ausgegeben\n-f, --fatal             = Nur Fatale Fehler ausgeben\n-e, --error             = Nur Fatale Fehler und Fehler ausgeben\n-w, --warn              = Fatale Fehler, Fehler und Warnungen ausgeben\n-u, --usage             = Informationen zur Nutzung bestimmter EPUB-Features ausgeben (standardmäßig deaktiviert);\n                          wenn aktiviert, dann werden Informationen immer auch in die Ausgabedatei aufgenommen.\n\n--locale <sprache>      = Ausgabe der Ergebnisse in der angegebenen Sprache, sofern eine Übersetzung verfügbar ist\n                          (Angabe nach IETF BCP 47 Standard)\n\n-l, --listChecks [<datei>]       = Ausgabe aller Message-ID's und Fehler-Level in eine\n                                   benutzerdefinierte Datei <datei> oder auf der Konsole.\n-c, --customMessages [<datei>]   = Überschreibt die Fehler-Level von EPUBCheck wie in der\n                                   benutzerdefinierten Datei <datei> angegeben.\n\n--version               = Zeigt die EPUBCheck-Versionsnummer an\n\n-h, -? oder --help      = Zeigt diese Hilfe an\n\n`,
  "es": `EPUBCheck v${EPUBCHECK_VERSION}\n\nPara ejecutar EPUBCheck el primer argumento debe ser el nombre (y la ruta)\ndel archivo que se valida.\n\nPara especificar un perfil de validación (ejecuta comprobaciones sobre un perfil\nEPUB 3 específico o una especificación), use la opción -profile:\n\nPerfiles de validación soportados:\n--profile default        = perfil de validación por defecto\n--profile dict           = valida sobre la especificación EPUB Diccionarios y Glosarios\n--profile edupub         = valida sobre el perfil EDUPUB \n--profile idx            = valida sobre la especificación EPUB Índices\n--profile preview        = valida sobre la especificación EPUB Vistas Previas\n\nSi se valida un archivo que no sea epub, la versión epub del archivo\ndebe especificarse con -v y el tipo de archivo con -mode.\nLa versión por defecto es: 3.0.\n\nModos y versiones soportados:\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0         = Para la validación de Media Overlays\n--mode exp               = Para archivos EPUB expandidos\n\nEsta herramientas permite las siguientes opciones:\n--save                   = guarda el epub creado a partir del epub expandido\n--out <file>             = extrae un fichero XML de validación\n                           (utilice - para salida a la consola)\n--xmp <file>             = extrae un fichero XMP de validación\n                           (utilice - para salida a la consola)\n--json <file>            = extrae un fichero JSON de validación\n                           (utilice - para salida a la consola)\n-m <file>                = igual a --mode\n-p <profile>             = igual a --profile\n-o <file>                = igual a --out\n-x <file>                = igual a --xmp\n-j <file>                = igual a --json\n--failonwarnings         = Por defecto, la herramienta devuelve 1 si se encuentran errores en el archivo o 0 si no hay errores\n                           Utilizar --failonwarnings provoca la detención del proceso con un resultado\n                           de 1 si hay errores o advertencias y 0 cuando no los hay.\n-q, --quiet              = no hay mensajes en la consola; excepto errores, solo en la salida\n-f, --fatal              = incluye solo errores en la salida\n-e, --error              = incluye solo errores y errores graves en la salida\n-w, --warn               = incluye solo errores, errores graves y advertencias en la salida\n-u, --usage              = incluye información sobre el uso de ePub en la salida\n                           (por defecto es OFF); si está activada, la información de uso será incluida\n                           en el archivo de salida\n--locale <locale>        = output localized messages according to the provided IETF BCP 47 language tag string.\n-l, --listChecks [<file>]       = enumera los identificadores de mensaje y los niveles de gravedad en el archivo\n                                  personalizado de mensajes <file> o en la consola\n-c, --customMessages [<file>]   = sobreescribe los niveles de gravedad del mensaje según los parámetros del\n                                  archivo personalizado de mensajes <file>\n\n--version                = displays the EPUBCheck version\n\n-h, -? or --help         = muestra este texto de ayuda\n\n`,
  "fr": `EPUBCheck v${EPUBCHECK_VERSION}\n\nPour utiliser cet outil, le premier argument doit être le nom (ou le chemin) du fichier à valider.\n\nPour spécifier un profil de validation (pour effectuer les vérifications spécifiques\nà un profil ou une extension EPUB 3), utilisez l’option -profile.\n\nProfils de validation acceptés:\n--profile default       = le profil de validation par défaut\n--profile dict          = vérifie les règles de la spécification Dictionnaires et Glossaires EPUB\n--profile edupub        = vérifie les règles du profil EDUPUB\n--profile idx           = vérifie les règles de la spécification Indexes EPUB\n--profile preview       = vérifie les règles de la spécification Aperçus EPUB\n\nEn cas de vérification d’un fichier simple inclus dans un EPUB, la version de la\nspécification EPUB à vérifier doit être spécifiée avec l’option -v et le type de \nfichier avec l’option -mode.\nLa version par défaut est 3.0.\n\nModes et versions acceptés: \n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0        = Pour une vérification des Media Overlays\n--mode exp              = Pour une vérification de répertoire EPUB non-compressé\n\nCet outil accepte également les options suivantes :\n--save                  = sauvegarde un EPUB créé depuis un EPUB non-compressé\n--out <file>            = produit un rapport de validation XML\n                          (utiliser - pour le produire sur la sortie standard)\n--xmp <file>            = produit un rapport de validation XMP\n                          (utiliser - pour le produire sur la sortie standard)\n--json <file>           = produit un rapport de validation JSON\n                          (utiliser - pour le produire sur la sortie standard)\n-m <file>               = identique à --mode\n-p <profile>            = identique à --profile\n-o <file>               = identique à --out\n-x <file>               = identique à --xmp\n-j <file>               = identique à --json\n--failonwarnings        = Par défaut, cet outil renvoie 1 si des erreurs sont trouvées ou 0 si le fichier\n                          ne contient aucune erreur. En utilisant --failonwarnings, 1 sera renvoyé également\n                          si des warnings ou des erreurs sont présents, et 0 ne sera renvoyés que si le fichier\n                          ne contient ni erreurs ni warnings.\n-q, --quiet             = seuls les messages d’erreurs sont produits sur la sortie standard.\n-f, --fatal             = inclure uniquement les erreurs fatales dans la sortie.\n-e, --error             = inclure uniquement les erreurs et erreurs fatales dans la sortie.\n-w, --warn              = inclure uniquement les erreurs, erreurs fatales, et warnings dans la sortie.\n-u, --usage             = inclure les informations d’usage dans la sortie (OFF par défaut) ;\n                          si cette option est activée, des informations d’usage apparaitront systématiquement\n                          dans les rapports de validation.\n--locale <locale>       = sortir des messages localisés conformément à la chaîne de balises de langue IETF BCP 47 fournie\n-l, --listChecks [<file>]       = liste les identificateurs de message et les niveaux de sévérité dans le fichier\n                                  de sortie <file> ou sur la sortie standard.\n-c, --customMessages [<file>]   = remplace les niveaux de sévérité par défaut par ceux contenus\n                                  dans le fichier <file>\n\n--version               = affiche la version EPUBCheck\n\n-h, -? ou --help        = affiche cette aide\n\n`,
  "it": `EPUBCheck v${EPUBCHECK_VERSION}\n\nIl primo argomento è il percorso completo del file da controllare.\n\nPer specificare un profilo di validazione (per eseguire i controlli rispetto ad uno specifico profilo EPUB 3\no specifica dell'estensione), utilizzare l'opzione --profilo:\n\nProfili di convalida supportati:\n--profile default       = il profilo di convalida predefinito\n--profile dict          = convalida in base alle specifiche dei dizionari e dei glossari EPUB\n--profile edupub        = convalida in base al profilo EDUPUB\n--profile idx           = convalida in base alle specifiche degli indici EPUB\n--profile preview       = è valida rispetto alla specifica EPUB Anteprime EPUB\n\nSe non si controlla un file EPUB, la versione EPUB deve essere specificata\nusando -v e il tipo di file usando --mode. La versione predefinita è la 3.0.\n\nTipi di controlli e corrispondenti versioni EPUB:\n--mode exp              = controlla file decompressi\n--mode mo -v 3.0        = controlla Media Overlays\n--mode nav -v 3.0       = controlla Navigation Document\n--mode opf -v 2.0       = controlla file OPF\n--mode opf -v 3.0       = controlla file OPF\n--mode svg -v 2.0       = controlla file SVG\n--mode svg -v 3.0       = controlla file SVG\n--mode xhtml -v 2.0     = controlla file XHTML\n--mode xhtml -v 3.0     = controlla file XHTML\n\nArgomenti opzionali:\n--save                  = crea un EPUB compresso alla fine del controllo\n--out <file>            = produci un documento XML coi risultati\n                          ('-' per l'output in console)\n--xmp <file>            = produci un documento XMP coi risultati\n                          ('-' per l'output in console)\n--json <file>           = produci un documento JSON coi risultati\n                          ('-' per l'output in console)\n-m <tipo>               = sinonimo di --mode\n-p <profile>            = same as --profile\n-o <file>               = sinonimo di --out\n-x <file>               = sinonimo di --xmp\n-j <file>               = sinonimo di --json\n--failonwarnings        = di norma, ritorna 1 se sono rilevati errori,\n                          e 0 altrimenti.\n                          Specificando --failonwarnings, sarà ritornato\n                          1 in presenza di errori o potenziali errori\n                          e 0 altrimenti.\n-q, --quiet             = non stampa messaggi in console, salvo errori\n-f, --fatal             = includi solo gli errori fatali nell'output\n-e, --error             = includi gli errori (fatali e non) nell'output\n-w, --warn              = includi gli errori (fatali e non) e\n                          i potenziali errori nell'output\n-u, --usage             = includi informazioni sull'uso delle\n                          varie specifiche EPUB nell'output;\n                          se abilitate, tali informazioni saranno\n                          sempre incluse nell'output <file>\n--locale <locale>       = output localized messages according to the\n                          provided IETF BCP 47 language tag string.\n-l,  --listChecks [<file>]      = salva gli id e i livelli di errore nel\n                                  file personalizzato <file> o stampali\n                                  nella console (se <file> è omesso)\n-c, --customMessages [<file>]   = ridefinisci i livelli di errore come\n                                  specificato nel file personalizzato <file>\n\n--version               = visualizza la versione EPUBCheck\n\n-h, -? o --help         = mostra questa guida\n\n`,
  "ja": `EPUBCheck v${EPUBCHECK_VERSION}\n\nこのツールを実行するには、最初の引数をチェックしたいファイルの(パスを含んだ)\n名前にして下さい.\n\n(特定のEPUB 3 プロファイルや拡張仕様に対してチェックするため)検証用プロファイルを\n指定するには, -profile オプションを使用します:\n\nサポートしている検証用プロファイル:\n--profile default        = デフォルトの検証用プロファイルを使用します\n--profile dict           = EPUB Dictionaries and Glossaries 仕様に対して検証します\n--profile edupub         = EDUPUB Profile に対して検証します\n--profile idx            = EPUB Indexes 仕様に対して検証します\n--profile preview        = EPUB Previews 仕様に対して検証します\n\n非epubファイルを検証する際は、-v オプションでepubのバージョンを、\n-modeオプションでファイル種別を指定します.\nデフォルトのバージョン: 3.0.\n\nサポートしている mode と version:\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0        = メディアオーバーレイ検証用\n--mode exp                  = 展開済みEPUBアーカイブ\n\n以下のオプションも受け付けます:\n--save                   = 展開されたepubパスから生成されたepubファイルを保存します\n--out <file>             = 評価結果のXML文書ファイルを出力します (コンソールへの出力には - を使用)\n--xmp <file>             = 評価結果のXMP文書ファイルを出力します (コンソールへの出力には - を使用)\n--json <file>            = 評価結果のXJSON文書ファイルを出力します (コンソールへの出力には - を使用)\n-m <file>                = --mode と同様\n-p <profile>             = --profile と同様\n-o <file>                = --out と同様\n-x <file>                = --xmp と同様\n-j <file>                = --json と同様\n--failonwarnings         = デフォルトでは、終了ステータスコードとして、エラーが検出されれば1を、検出されなければ\n                           0を返します. --failonwarnings オプションを指定すると、警告かエラーがあれば1を、警告もエラーもどちらも\n                           ない場合のみ0を返すようになります.\n-q, --quiet              = エラー以外のメッセージをコンソールに出力しないようにします\n-f, --fatal              = fatal レベルの深刻度のエラーメッセージのみを出力します\n-e, --error              = fatal レベルと error レベルの深刻度のエラーメッセージのみを出力します\n-w, --warn               = fatal、error、warn レベルの深刻度のエラーメッセージを出力します\n-u, --usage              = epubの利用法情報も出力します\n                           (デフォルトは OFF です); 指定した場合、利用法情報は\n                           出力ファイルに常に含まれるようになります\n--locale <locale>        = 指定されたIETF BCP 47 言語タグ文字列に対応するローカライズメッセージを出力します.\n-l, --listChecks [<file>]       = メッセージIDと深刻度レベルをカスタムメッセージファイル <file> または\n                                  コンソールに出力します\n-c, --customMessages [<file>]   = カスタムメッセージファイル <file> でメッセージ深刻度レベルを上書きします\n\n--version                = EPUBCheckのバージョンを表示します\n\n-h, -? or --help         = ヘルプメッセージを表示します\n\n`,
  "ko-KR": `EPUBCheck v${EPUBCHECK_VERSION}\n\n유효성 검사를 실행하려면 경로를 포함한 파일명을 지정하십시요.\n\n유효성 검사를 위해 특정한 프로파일을 지정하려면 (특정한 EPUB3 혹은 확장된 사양 등) -profile 옵션을 사용합니다 :\n\n지원하는 유효성 검사 프로파일 : \n--profile default        = 기본 검증용 프로파일을 사용합니다.\n--profile dict           = EPUB Dictionaries and Glossaries 사양에 대해 확인합니다.\n--profile edupub         = EDUPUB profile에 대해 확인합니다.\n--profile idx            = EPUB Indexes 사양에 대해 확인합니다.\n--profile preview        = ePUB Previews 사양에 대해 확인합니다\n\n비 epub 파일을 확인할 때 -v 옵션에서 epub 버전을 -mode 옵션에서 파일 유형을 지정합니다.\n기본 버전 : 3.0.\n\n지원 mode와 version :\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0         = 미디어 오버레이 검증시\n--mode exp               = EPUB 아카이브 확장시\n\n다음 옵션을 사용할 수 있습니다:\n--save                   = 확장 된 epub 경로에 생성 된 epub 파일을 저장합니다.\n--out <file>             = 유효성 검사 결과를 XML 문서로 출력 합니다 (콘솔 출력은 -을 사용)\n--xmp <file>             = 유효성 검사 결과를 XMP 문서로 출력합니다 (콘솔 출력은 -을 사용)\n--json <file>            = 유효성 검사 결과를 JSON 문서로 출력합니다 (콘솔 출력은 -을 사용)\n-m <file>                = --mode와 같음\n-p <profile>             = --profile과 같음\n-o <file>                = --out과 같음\n-x <file>                = --xmp와 같음\n-j <file>                = --json과 같음\n--failonwarnings         = 유효성 검사를 완료한 후 오류가 검출되면 1을 오류가 없으면 0을 반환합니다.\n                           --failonwarnings 옵션을 지정하면 경고 또는 오류가있는 경우 1을 모두 없을 경우에만 0을 반환합니다.\n-q, --quiet              = 오류를 제외하고 화면에 메시지를 출력하지 않습니다.\n-f, --fatal              = 심각한 오류 메시지만 출력 파일에 표시합니다.\n-e, --error              = 오류와 심각한 오류 메시지를 출력 파일에 표시합니다.\n-w, --warn               = 경고, 오류, 심각한 오류 메시지를 출력 파일에 표시합니다.\n-u, --usage              = epub 이용법 정보를 출력합니다.(기본값 : OFF) ON으로 지정한 경우 이용법 정보가 출력 파일에 포함됩니다.\n--locale <locale>        = output localized messages according to the provided IETF BCP 47 language tag string.\n-l, --listChecks [<file>]       = 메시지 ID와 심각도 레벨을 출력 파일 <file> 또는 콘솔에 출력합니다 \n-c, --customMessages [<file>]   = 출력 파일 <file>에서 메시지 심각도 레벨을 덮어 씁니다\n\n--version                = EPUBCheck의 버전을 표시합니다.\n\n-h -? or --help          = 도움말 메시지를 표시합니다.\n\n`,
  "nl": `EPUBCheck v${EPUBCHECK_VERSION}\n\nBij het starten van dit programma wordt als eerste argument de bestandsnaam\n(inclusief directorypad) van het te controleren bestand verwacht.\n\nOm een validatieprofiel te specificeren (om te checken tegen een specifiek ePub 3 profiel\nof extensiespecificatie), gebruikt u de -profile optie:\n\nOndersteunde validatieprofielen:\n--profile default       = het standaard validatieprofiel\n--profile dict          = valideert tegen de ePub Dictionaries & Glossaries specificatie\n--profile edupub        = valideert tegen de EDUPUB specificatie\n--profile idx           = valideert tegen de ePub Indexes specificatie\n--profile preview       = valideert tegen de ePub Previews specificatie\n\nAls u een bestand wilt controleren dat geen epub is moet de epub-versie worden\ngespecificeerd met gebruik van -v en het type bestand met gebruik van -mode.\nDe standaardversie is 3.0.\n\nDe ondersteunde modes en versies:\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0        = Voor het valideren van Media Overlays\n--mode exp              = Voor uitgepakte epub structuren\n\nDit programma accepteert ook de volgende optionele instellingen:\n--save                  = slaat een epub op vanuit de uitgepakte epub structuur\n--out <file>            = geeft een XML bestand met het resultaat van de check\n                          (- gebruiken om naar de console uit te voeren)\n--xmp <file>            = geeft een XMP bestand met het resultaat van de check\n                          (- gebruiken om naar de console uit te voeren)\n--json <file>           = geeft een JSON bestand met het resultaat van de check\n                          (- gebruiken om naar de console uit te voeren)\n-m <file>               = gelijk aan --mode\n-p <profile>            = gelijk aan --profile\n-o <file>               = gelijk aan --out\n-x <file>               = gelijk aan --xmp\n-j <file>               = gelijk aan --json\n--failonwarnings.       = standaard geeft het programma een waarde van 1 als er fouten worden gedetecteerd\n                          en een waarde van 0 als alles OK is.\n                          Gebruik --failonwarnings als u wilt dat er een waarde van 1 wordt teruggegeven als er fouten \n                          OF waarschuwingen worden ontdekt. \n                          Een waarde van 0 betekent dat er fouten noch waarschuwingen gedetecteerd zijn.\n-q, --quiet             = geen berichten in de console, afgezien van eventuele foutmeldingen. In de output vindt u wel alles terug.\n-f, --fatal             = meldt alleen fatale fouten in de output\n-e, --error             = meldt alleen foutmeldingen en berichten met fatale afloop in de output\n-w, --warn              = zowel fatale, foutmeldingen en waarschuwingen in de output\n-u, --usage             = vermeldt de instellingen van dit programma in de output\n                          (standaard staat dit OFF); wanneer dit op ON staat wordt deze\n                          informatie altijd weergegeven in het outputbestand.\n--locale <locale>       = output localized messages according to the provided IETF BCP 47 language tag string.\n-l, --listChecks [<file>]       = geeft bericht IDs en zwaartegraden weer in het berichtenbestand\n                                  met de naam <file> of het console. \n-c, --customMessages [<file>]   = gebruikt de zwaartegraden uit het aparte berichtenbestand\n                                  met de naam <file>\n\n--version               = geeft de EPUBCheck-versie weer\n\n-h, -? of --help        = geeft dit hulpbestand weer\n\n`,
  "pt-BR": `EPUBCheck v${EPUBCHECK_VERSION}\n\nAo executar esta ferramenta, o primeiro argumento deve ser o nome (com o caminho)\ndo arquivo a ser verificado.\n\nPara especificar um perfil de validação (para verificações sob um perfil específico do EPUB 3\nou especificação de extensão), use a opção -profile:\n\nPerfis de validação suportados:\n--profile default       = o perfil de validação padrão\n--profile dict          = valida sob a especificação de Dicionários e Glossários EPUB\n--profile edupub        = valida sob o Perfil EDUPUB\n--profile idx           = valida sob a especificação de Índices EPUB\n--profile preview       = valida sob a especificação de Amostras EPUB\n\nSe estiver verificando um arquivo que não seja epub, a versão epub do arquivo deve\nser especificada usando -v e o tipo do arquivo usando -mode.\nA versão padrão é: 3.0.\n\nModos e versão suportadas: \n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0        = para validação de Media Overlays\n--mode exp              = para arquivos EPUB expandidos\n\nEsta ferramenta também aceita as seguintes opções:\n--save                  = salva o epub criado a partir do epub expandido\n--out <arquivo>         = gera um arquivo de avaliação no formato XML (uso - para exibir no console)\n--xmp <arquivo>         = gera um arquivo de avaliação no formato XMP (uso - para exibir no console)\n--json <arquivo>        = gera um arquivo de avaliação no formato JSON (uso - para exibir no console)\n-m <arquivo>            = o mesmo que --mode\n-p <perfil>             = o mesmo que --profile\n-o <arquivo>            = o mesmo que --out\n-x <arquivo>            = o mesmo que --xmp\n-j <arquivo>            = o mesmo que --json\n--failonwarnings        = Por padrão, a ferramenta retorna 1 se erros forem encontrados no arquivo ou 0 se não forem\n                          encontrados erros.  Usar --failonwarnings irá fazer com que o processo finalize com o status de\n                          1 se houver tanto advertências como falhas presentes e 0 apenas quando não houver erros nem advertências.\n-q, --quiet             = nenhuma mensagem no console, exceto erros, apenas na saída\n-f, --fatal             = incluir apenas erros fatais na saída\n-e, --error             = incluir apenas mensagens com severidade de erro e erro fatal na saída\n-w, --warn              = incluir apenas mensagens com severidade de erro fatal, erro, e advertência na saída\n-u, --usage             = incluir informação sobre o uso de recursos ePub na saída\n                          (o padrão é desligado); se habilitato, a informação sobre o uso será\n                          sempre incluída no arquivo de saída\n--locale <idioma>       = gera mensagens no idioma local, de acordo com o código de linguagem fornecido pela norma IETF BCP 47.\n-l, --listChecks [<arquivo>]      = lista ids de mensagem e o nível de severidade para o arquivo de mensagem personalizada de nome <arquivo>\n                                    ou no console\n-c, --customMessages [<arquivo>]  = sobrescreve os níveis de severidade das mensagens como definido no arquivo de mensagem personalizada de nome <arquivo>\n\n--version               = exibe a versão do EPUBCheck\n\n-h, -? ou --help        = exibe esta mensagem de ajuda\n\n`,
  "zh-TW": `EPUB檢查器 ${EPUBCHECK_VERSION}版\n\n當使用本工具時，第一個變數需是要檢查的檔案名稱（包含路徑）。\n\n要指定驗證Profile（以檢查特定的EPUB Profile或者延伸規格），請使用 -profile 選項如下：\n\n驗證Profile支援如下：\n--profile default = 以預設profile驗證\n--profile dict = 以EPUB 字典與詞彙表規格進行驗證\n--profile edupub = 以EDUPUB Profile進行驗證\n--profile idx = 以EPUB 索引規格進行驗證\n--profile preview = 以EPUB預覽規格進行驗證\n\n如果檢查的不是EPUB檔案，則必須使用 -mode 來指定檔案種類，以及使用 -v 來指定版本。\n預設版本為：3.0。\n\n支援的檔案種類與版本如下：\n--mode opf -v 2.0\n--mode opf -v 3.0\n--mode xhtml -v 2.0\n--mode xhtml -v 3.0\n--mode svg -v 2.0\n--mode svg -v 3.0\n--mode nav -v 3.0\n--mode mo -v 3.0 = 供檢查Media Overlays功能使用\n--mode exp = 供擴張的EPUB檔案使用\n\n本工具也接受下列項目：\n--save = 另由擴張的EPUB中儲存EPUB\n--out<file> = 輸出結果為XML格式的檔案（使用 - 以輸出到終端機）\n--xmp <file> = 輸出結果為XMP格式的檔案（使用 - 以輸出到終端機）\n--json <file> =  輸出結果為XMP格式的檔案（使用 - 以輸出到終端機）\n-m <file> = 和 --mode 相同\n-p <profile> = 和 --profile 相同\n-o <file> = 和 --out 相同\n-x <file> = 和 --xmp 相同\n-j <file> = 和 --json 相同\n--failonwarnings      = 預設上，當發現錯誤時回報值為 1 或者沒有錯誤時回報值為 0。使用 --failonwarnings 將會使得處理程序終止，狀態為 1 並且有警告訊息或者錯誤需要顯示亦然，而只會在沒有錯誤與警告訊息時才會回傳 0。\n-q, --quiet = 除了錯誤以外不會在終端機上顯示訊息，但僅限於結果\n-f, --fatal = 結果僅包含致命錯誤\n-e, --error = 結果僅包含錯誤以及致命錯誤\n-w, --warn = 結果包含致命錯誤、錯誤與警告訊息\n-u, --usage = 結果包含EPUB中使用的功能訊息（預設為關閉）；若開啟，使用的功能資訊將會持續出現在結果檔案中\n--locale <locale> = 根據所提供的IETF BCP 47語言標籤字串輸出在地化的訊息\n-l, --listChecks [<file>] = 列出訊息ID以及重要層級到指定的輸出訊息檔案<file>\n或者終端機\n-c, --customMessages [<file>] = 忽視指定的輸出訊息檔案<file>中的訊息重要層級\n\n--version = 顯示EPUB檢查器版本\n\n-h, -? 或 --help = 顯示輔助說明訊息\n\n`,
};
